const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const htmlEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=htmlEscape;
const url=v=>{try{const u=new URL(String(v));return ['https:','http:'].includes(u.protocol)?E(u.href):'#'}catch{return '#'}};
const text=(v,empty='Not established')=>v===null||v===undefined||v===''?empty:E(typeof v==='object'?JSON.stringify(v):v);
const A=v=>Array.isArray(v)?v:[];
const O=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
const ds=v=>v?new Date(v).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
const numfmt=n=>new Intl.NumberFormat(undefined,{maximumFractionDigits:1}).format(n);
function metricQuantity(key,v){if(state.settings.units!=='metric'||v==null||v===''||!Number.isFinite(Number(v)))return {key,value:v};const n=Number(v),k=String(key).toLowerCase();if(k.endsWith('_lb')||k.includes('weight_lb'))return {key:String(key).replace(/_lb$/,'_kg'),value:numfmt(n*.45359237)+' kg'};if(k.endsWith('_ft')||k.includes('altitude_ft'))return {key:String(key).replace(/_ft$/,'_m'),value:numfmt(n*.3048)+' m'};if(k.endsWith('_nm'))return {key:String(key).replace(/_nm$/,'_km'),value:numfmt(n*1.852)+' km'};return {key,value:v}}

const storeKey='aeromission-ai-v3';const defaults={view:'dashboard',tab:'overview',selected:'',jobSelected:'',missions:[],jobs:[],fleet:[],logbook:[],taskId:'',settings:{theme:'dark',units:'imperial',homeBase:'',defaultStart:'',pic:'',mxStatus:'OK',ageInfluence:true,vatsimCid:'',vatsimEnabled:true,appPasscode:''},vatsim:{pilot:null,lastChecked:null,error:null}};
let state=load(),health={ok:false,aiConfigured:false},taskState=null,polling=false,flightTimer=null;
function load(){try{const s=JSON.parse(localStorage.getItem(storeKey)||'{}');return {...defaults,...s,settings:{...defaults.settings,...O(s.settings)},missions:A(s.missions),jobs:A(s.jobs),fleet:A(s.fleet),logbook:A(s.logbook)}}catch{return structuredClone(defaults)}}
function save(){try{localStorage.setItem(storeKey,JSON.stringify(state))}catch{notify('Browser storage is full. Export a backup.',true)}}
function notify(s,error=false){const t=document.createElement('div');t.className='toast'+(error?' fail':'');t.textContent=s;$('#toast-region').appendChild(t);setTimeout(()=>t.remove(),6200)}
async function api(path,data){let r;try{r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{Accept:'application/json',...(state.settings.appPasscode?{'X-AeroMission-Passcode':state.settings.appPasscode}:{}),...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)})}catch(e){throw Error('Unable to reach AeroMission server. '+e.message)}const ct=r.headers.get('content-type')||'';if(!ct.includes('application/json'))throw Error(`Server returned ${ct||'non-JSON'} from ${path}. Check that the NEW AI rebuild was deployed on Render (HTML response indicates an old server or misrouted API).`);const value=await r.json();if(!r.ok)throw Error(value?.error||`HTTP ${r.status}`);return value}
const S=()=>state.missions.find(m=>m.id===state.selected)||state.missions[0]||null;
const nav=[['dashboard','◫','Dashboard'],['builder','✦','Mission Builder'],['dispatch','◈','Dispatch'],['jobs','▤','Job Board'],['fleet','✈','Fleet / MX'],['flight','◉','Live Flight'],['logbook','▧','Logbook'],['settings','⚙','Settings']];
const titles={dashboard:'Operations overview',builder:'AI mission builder',dispatch:'Flight dispatch',jobs:'AI charter board',fleet:'Aircraft & maintenance',flight:'VATSIM live flight',logbook:'Flight logbook',settings:'System settings'};
const tag=(s,type='')=>`<span class="tag ${type}">${E(s||'UNAVAILABLE')}</span>`;
const btn=(action,label,style='')=>`<button type="button" class="button ${style}" data-action="${E(action)}">${E(label)}</button>`;
const row=(k,v)=>`<div class="kv"><b>${E(k)}</b><span>${text(v)}</span></div>`;
const textList=(values)=>A(values).length?A(values).map(x=>`<div class="tiny" style="margin:7px 0">• ${text(typeof x==='object'?JSON.stringify(x):x)}</div>`).join(''):'<div class="tiny">Not established</div>';
const links=values=>A(values).length?A(values).map(x=>`<div class="source"><a href="${url(x)}" target="_blank" rel="noopener noreferrer">${E(x)}</a></div>`).join(''):'<div class="tiny">No supporting URL recorded</div>';
const card=(heading,content,extra='')=>`<section class="card ${extra}"><h3>${E(heading)}</h3>${content}</section>`;
function upsert(m){if(!m?.id)return;const at=state.missions.findIndex(x=>x.id===m.id);if(at>=0){const current=state.missions[at];state.missions[at]={...m,status:current.status==='COMPLETED'?'COMPLETED':m.status}}else state.missions.unshift(m);state.selected=m.id;save()}
function updateTheme(){document.body.classList.toggle('light',state.settings.theme==='light')}
function shell(){updateTheme();const active=state.view in views?state.view:'dashboard';$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-icon">✈</div><div><div class="brand-title">Aero<span>Mission</span></div><small>AI OPERATIONS / V3</small></div></div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ico,title])=>`<button type="button" data-nav="${id}" class="${active===id?'active':''}" title="${title}" ${active===id?'aria-current="page"':''}><span class="ico">${ico}</span><span class="nav-label">${E(title)}</span></button>`).join('')}</nav><div class="sidefoot"><span class="online-dot ${health.aiConfigured?'':'off'}"></span>${health.aiConfigured?'AI SERVICE CONFIGURED':'AI CONFIGURATION REQUIRED'}<div>VATSIM ${state.settings.vatsimCid?'CID CONFIGURED':'CID NOT SET'}</div><div>v3.0.0 • SIMULATION ONLY</div></div></aside><main class="main"><header class="top"><div><div class="eyebrow">FLIGHT OPERATIONS / AI SIMULATOR</div><h1>${E(titles[active])}</h1></div><div class="top-right">${tag(health.aiConfigured?'AI CONNECTED':'AI KEY REQUIRED',health.aiConfigured?'ok':'warn')}<span class="pill">SIMULATION / NOT FOR FLIGHT</span></div></header><div class="content" id="content">${taskBanner()}${views[active]()}</div></main></div>`;bind()}
function taskBanner(){if(!state.taskId)return '';if(!taskState)return `<div class="progress"><strong>Resuming an AI task…</strong></div>`;const history=A(taskState.history).slice(-7),failure=taskState.status==='FAILED';return `<div class="progress"><header><strong>${E(taskState.kind)} / ${E(taskState.stage)}</strong>${tag(taskState.status,failure?'fail':taskState.status==='COMPLETE'?'ok':'warn')}</header><p>${E(taskState.detail||'AI is working. Research and interpretation can take several minutes.')}${failure?` — ${E(taskState.error)}`:''}</p><div class="timeline">${history.map(x=>`<span>${E(x.stage)}</span>`).join('')}</div><div class="actions" style="margin-top:10px">${btn('dismiss-task',failure?'Dismiss error':'Hide task status','small secondary')}<span class="tiny">Jobs run on the Render server; the mission is saved as soon as AI returns an itinerary. Refreshing may resume this task.</span></div></div>`}
function dashboard(){const m=S(),research=m?.research?.status||'—',tracked=state.logbook.filter(x=>x.source==='VATSIM_LIVE').length;return `<section class="hero"><div><div class="overline" style="color:#9bcfff">MISSION OPERATIONS / AI-GENERATED</div><h2>Real aircraft. Original missions. Deeper simulation.</h2><p>AI constructs every mission, researches registration evidence, models age-sensitive maintenance, and prepares departure, destination and alternate briefings with ground support and fuel research.</p></div>${btn('open-builder','Generate an AI mission')}</section><section class="stats"><div class="stat"><div class="overline">MISSIONS</div><div class="number">${state.missions.length}</div><div class="tiny">saved to this device</div></div><div class="stat"><div class="overline">AVAILABLE JOBS</div><div class="number">${state.jobs.filter(j=>j.status!=='ASSIGNED').length}</div><div class="tiny">AI charter assignments</div></div><div class="stat"><div class="overline">AIRCRAFT</div><div class="number">${state.fleet.length}</div><div class="tiny">researched fleet records</div></div><div class="stat"><div class="overline">VATSIM SESSIONS</div><div class="number">${tracked}</div><div class="tiny">observed in browser</div></div></section><div class="grid two">${card('Current mission',m?`${tag(m.status,'ok')} ${tag(research,research==='COMPLETE'?'ok':'warn')}<h2 style="font:800 19px Manrope;margin:15px 0 9px">${E(m.title)}</h2><div class="route">${A(m.legs).map(l=>E(l.origin)).concat(A(m.legs).slice(-1).map(l=>E(l.destination))).join(' → ')}</div><p class="tiny">${E(m.aircraft?.model||m.aircraft?.icao_type||'Aircraft pending')} / ${E(m.aircraft?.registration||'registration pending')}</p><p class="tiny">${E(m.research?.summary||'Airport research still pending')}</p><div class="actions">${btn('open-dispatch','Open dispatch','small')}${btn('pdf','Download full dispatch PDF','small secondary')}</div>`:'<div class="empty"><strong>No active mission</strong>Create your first AI-generated aircraft charter mission.</div>')}${card('Readiness & connectivity',`${row('OpenAI API',health.aiConfigured?'Configured':'Missing OPENAI_API_KEY')}${row('Model',health.model||'—')}${row('VATSIM CID',state.settings.vatsimCid?'Configured locally':'Not set')}${row('Last VATSIM check',ds(state.vatsim.lastChecked))}${row('App storage','Browser localStorage; export backups')}<div class="panel-note" style="margin-top:14px">AI results and public data are simulation references. Aircraft registry matches, MEL/CDL, published frequencies and fuel prices always require independent verification.</div>`)}</div><div class="section-head"><h2>Recent missions</h2>${btn('open-jobs','Browse AI jobs','small secondary')}</div>${missionTable(state.missions.slice(0,8))}`}
function missionTable(missions){if(!missions.length)return '<div class="empty">No missions to display.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Mission</th><th>Itinerary</th><th>Aircraft</th><th>Research</th><th></th></tr></thead><tbody>${missions.map(m=>`<tr><td><strong>${E(m.title)}</strong><div class="tiny mono">${E(m.code)}</div></td><td class="mono">${E(A(m.legs).map(x=>x.origin).concat(A(m.legs).slice(-1).map(x=>x.destination)).join(' → '))}</td><td>${E(m.aircraft?.registration||'Researching')}<div class="tiny">${E(m.aircraft?.model||m.aircraft?.icao_type)}</div></td><td>${tag(m.research?.status||'PENDING',m.research?.status==='COMPLETE'?'ok':'warn')}</td><td><button class="button small secondary" data-open="${E(m.id)}">Open</button></td></tr>`).join('')}</tbody></table></div>`}
function builder(){const s=state.settings;return `<div class="grid two"><section class="card"><h3>Mission requirements</h3><div class="panel-note">Blank fields leave decisions with AI. Nothing here is replaced with deterministic sample missions. All airport routes and the scenario are selected or interpreted by AI.</div><form id="mission-form" style="margin-top:20px"><div class="field-grid"><div class="field"><label>Mission category</label><select name="mission_type"><option value="">AI decides</option>${['Passenger charter','Air ambulance','Urgent cargo','Business aviation','Special operations support','Crew transfer','Scientific logistics','Government liaison','Aircraft positioning','Random complex assignment'].map(x=>`<option>${E(x)}</option>`).join('')}</select></div><div class="field"><label>Aircraft type / ICAO</label><input name="aircraft_type" placeholder="BE58 / H25B / C25C / AI decides"></div><div class="field"><label>Real aircraft registration</label><input name="registration" placeholder="N721RF / G-XXXX / AI selects"></div><div class="field"><label>Starting airport / region</label><input name="starting_point" value="${E(s.defaultStart||s.homeBase||'')}" placeholder="KIND / India / Caribbean / AI global"></div><div class="field"><label>Requested number of legs</label><input name="leg_count" type="number" min="1" max="10" placeholder="AI decides"></div><div class="field"><label>Difficulty</label><select name="difficulty"><option>AI DECIDES</option><option>ROUTINE</option><option>MODERATE</option><option>CHALLENGING</option><option>EXTREME</option></select></div><div class="field"><label>Aircraft maintenance status</label><select name="mx_status"><option ${s.mxStatus==='GOOD'?'selected':''}>GOOD</option><option ${s.mxStatus==='OK'?'selected':''}>OK</option><option ${s.mxStatus==='BAD'?'selected':''}>BAD</option></select></div><div class="field"><label>Current aircraft restrictions</label><input name="aircraft_status" placeholder="AI decides / serviceable / deferred items"></div></div><label class="checkbox"><input name="age_influence" type="checkbox" ${s.ageInfluence!==false?'checked':''}> Aircraft age influences simulated reliability and INOP likelihood</label><div class="field"><label>Optional custom mission concept</label><textarea name="concept" placeholder="Describe a mission, cargo type, region, client need, unusual circumstances, or leave entirely to AI"></textarea></div><button class="button" type="submit" ${state.taskId?'disabled':''}>✦ Generate complete AI mission</button><p class="tiny">Two-stage AI concept → structured mission → registration check → MX simulation → AI briefing for all airport stops. This process can take several minutes.</p></form></section>${card('How this rebuild operates',`<div class="subsection">01 / AI mission concept</div><p class="tiny">Original charter profile, aircraft type, real airports, schedule, passenger and cargo manifests, mission constraints.</p><div class="subsection">02 / AI route & flight planning</div><p class="tiny">Structured sequential legs with numeric noncertified fuel, TOLD and W&B simulation estimates. Invalid routes undergo AI correction.</p><div class="subsection">03 / Real-tail research</div><p class="tiny">Separate registry research. Registration is marked VERIFIED only with evidence; mismatches remain flagged.</p><div class="subsection">04 / Age & maintenance</div><p class="tiny">GOOD / OK / BAD adjusts a scenario risk score, influencing AI-generated INOP equipment, MEL/CDL-style caveats and MSFS steps.</p><div class="subsection">05 / Airport documentation</div><p class="tiny">Web research → separate AI interpretation, crosschecked against reference aerodrome data, for every departure, destination and alternate. Provider and fuel quotes/estimates are attributed.</p><div class="subsection">06 / Release & PDF</div><p class="tiny">Saved mission, detailed Dispatch pages and downloadable multipage PDF. Partial findings are explicitly marked.</p><div class="panel-note warn" style="margin-top:14px">AI-powered doesn't mean infallible. A missing API key or failed external search is reported, never silently replaced with fictional verified data.</div>`)}</div><div class="section-head"><h2>Previously generated missions</h2></div>${missionTable(state.missions)}`}
function jobs(){return `<section class="card"><h3>New AI job board</h3><form id="jobs-form" class="field-grid"><div class="field"><label>Starting point / region</label><input name="starting_point" value="${E(state.settings.defaultStart||'')}" placeholder="KIND / Europe / global"></div><div class="field"><label>Operation focus</label><select name="operation"><option>AI DECIDES</option><option>Passenger</option><option>Air cargo</option><option>Specialized charter</option><option>Emergency services support</option><option>All types</option></select></div><div class="field"><label>Aircraft type / class</label><input name="aircraft_type" placeholder="AI DECIDES"></div><div class="field"><label>Minimum distance (NM)</label><input name="min_nm" type="number" min="0" placeholder="75"></div><div class="field"><label>Maximum distance (NM)</label><input name="max_nm" type="number" min="0" placeholder="2000"></div><div class="field"><label>Aircraft maintenance</label><select name="mx_status"><option>RANDOM</option><option>GOOD</option><option>OK</option><option>BAD</option></select></div><div class="field"><label>Difficulty</label><select name="difficulty"><option>ALL LEVELS</option><option>EASY</option><option>MODERATE</option><option>HARD</option></select></div><div class="field"><label>Number of jobs</label><input name="count" type="number" min="1" max="12" value="6"></div><div class="field" style="justify-content:end"><button class="button" type="submit" ${state.taskId?'disabled':''}>✦ Generate AI assignments</button></div></form></section><div class="section-head"><h2>Assignments (${state.jobs.length})</h2><span class="tiny">AI-generated scenarios; select one to review.</span></div><div class="two-col"><div>${state.jobs.length?state.jobs.map(j=>`<div class="item ${state.jobSelected===j.id?'selected':''}" data-job="${E(j.id)}"><div class="job-route">${E(j.route.join(' → '))}</div><h3>${E(j.title)}</h3><p>${E(j.type)} · ${E(j.aircraft_type||'AI aircraft')} · ${E(j.difficulty||'Variable')}</p><p style="margin-top:7px">${E(j.description.slice(0,180))}</p><div style="margin-top:9px">${tag(j.status||'AVAILABLE',j.status==='ASSIGNED'?'ok':'')}</div></div>`).join(''):'<div class="empty"><strong>No assignments</strong>Generate a fresh AI job board.</div>'}</div><div>${jobDetail()}</div></div>`}
function jobDetail(){const j=state.jobs.find(x=>x.id===state.jobSelected)||state.jobs[0];if(!j)return card('Assignment detail','<div class="tiny">Select an AI assignment once generated.</div>');return card('Assignment detail',`${tag(j.type)} ${tag(j.mx_status||'OK')}<h2 style="font:800 19px Manrope;margin:15px 0 12px">${E(j.title)}</h2><div class="route">${E(j.route.join(' → '))}</div><p class="prose">${E(j.mission_profile||j.description)}</p>${row('Aircraft request',j.aircraft_type)}${row('Difficulty',j.difficulty)}${row('Distance band',`${j.minimum_nm??'—'}–${j.max_nm??'—'} NM`)}${row('Weather / logistics',j.weather_note)}<div class="actions" style="margin-top:20px"><button class="button" data-accept="${E(j.id)}" ${state.taskId?'disabled':''}>Create full AI mission from job</button></div><p class="tiny">The AI expands the assignment, chooses aircraft, researches its registration and builds all Dispatch records.</p>`) }
function dispatch(){const m=S();if(!m)return '<div class="empty"><strong>No mission selected</strong>Generate an AI mission or accept a job board assignment.</div>';const allA=A(m.airport_briefings),airReady=allA.filter(x=>x.status==='RESEARCHED').length;return `<div class="card"><div class="actions" style="justify-content:space-between"><div style="flex:1;min-width:230px"><label class="overline" for="select-mission">Selected mission</label><select id="select-mission" style="width:100%;margin-top:7px;border:1px solid var(--stroke);padding:10px;border-radius:8px;background:var(--bg2);color:var(--text)">${state.missions.map(x=>`<option value="${E(x.id)}" ${m.id===x.id?'selected':''}>${E(x.code)} — ${E(x.title)}</option>`).join('')}</select></div><div class="actions">${btn('pdf','↓ Full dispatch PDF')}${btn('retry-all','↻ Re-research all airports','secondary')}${btn('complete-mission','✓ Mark simulated complete','small secondary')}${btn('delete-mission','Delete mission','danger small')}</div></div></div><div class="grid three" style="margin-top:14px">${card('Mission / aircraft',`${tag(m.status)} ${tag(m.aircraft?.registration_status,m.aircraft?.registration_status==='VERIFIED'?'ok':'warn')}<h3 style="margin-top:14px">${E(m.title)}</h3><div class="tiny">${E(m.code)}</div>${row('Tail',m.aircraft?.registration)}${row('Model',m.aircraft?.model||m.aircraft?.icao_type)}${row('MX condition',m.mx_status)}`)}${card('Flight itinerary',`<h3>${A(m.legs).length} flight legs</h3><div class="route">${E(A(m.legs).map(x=>x.origin).concat(A(m.legs).slice(-1).map(x=>x.destination)).join(' → '))}</div>${row('Crew',A(m.crew).length)}${row('Passengers',A(m.passengers).length)}${row('Cargo entries',A(m.cargo).length)}`)}${card('Research & release',`${tag(m.research?.status||'QUEUED',m.research?.status==='COMPLETE'?'ok':'warn')}<h3 style="margin-top:14px">${airReady}/${allA.length} airports meet checks</h3><p class="tiny">${E(m.research?.summary||'Research in progress or not started.')}</p>${A(m.research?.errors).length?`<div class="panel-note fail">${A(m.research.errors).map(x=>`${E(x.subject)}: ${E(x.error)}`).join('<br>')}</div>`:''}`)}</div><div class="tabs">${[['overview','Mission profile'],['legs','Legs / fuel / performance'],['airports','Airport briefings'],['mx','MEL / CDL / MSFS'],['documents','Documents / manifest']].map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-tab="${id}">${E(label)}</button>`).join('')}</div>${({overview:dispatchOverview,legs:dispatchLegs,airports:dispatchAirports,mx:dispatchMx,documents:dispatchDocs}[state.tab]||dispatchOverview)(m)}`}
function dispatchOverview(m){return `<div class="grid two">${card('Operational mission profile',`<h3>${E(m.title)}</h3><p class="prose">${E(m.mission_profile||m.scenario||m.description)}</p><div class="subsection">Special instructions</div>${textList(m.requirements)}`)}${card('Aircraft registration evidence',`${row('Registration',m.aircraft?.registration)}${row('Verification',m.aircraft?.registration_status)}${row('Type',m.aircraft?.icao_type)}${row('Model',m.aircraft?.model)}${row('Manufactured',m.aircraft?.year_built)}${row('Simulation age',m.risk?.age_years===null?'Unknown':`${m.risk.age_years} years`)}${row('Scenario risk',`${m.risk?.risk_band||'Unknown'} / score ${m.risk?.simulation_risk_score??'—'}`)}${row('Registry note',m.aircraft?.registration_note)}<div class="subsection">Registration sources</div>${links(m.aircraft?.registration_sources)}<div class="panel-note warn" style="margin-top:12px">Even VERIFIED means AI found an apparent matching public source; an operator must independently check current registry status.</div>`)}</div>`}
function formatObj(o){return Object.entries(O(o)).map(([k,v])=>{const q=metricQuantity(k,v);return row(q.key.replaceAll('_',' ').replaceAll(/\b\w/g,x=>x.toUpperCase()),q.value)}).join('')||'<p class="tiny">No AI numeric planning data returned.</p>'}
function dispatchLegs(m){return A(m.legs).map((l,i)=>`<section class="airport"><div class="actions" style="justify-content:space-between"><h3>LEG ${i+1} / ${E(l.origin)} → ${E(l.destination)}</h3>${tag(l.planning_status||'SIMULATION', 'warn')}</div><div class="grid three">${card('Schedule / route',`${row('Departure UTC',ds(l.departure_utc))}${row('Arrival UTC',ds(l.arrival_utc))}${row('Distance',l.distance_nm==null?'Not estimated':state.settings.units==='metric'?`${numfmt(l.distance_nm*1.852)} km`:`${l.distance_nm} NM`)}${row('Flight time',l.flight_time_hours===null?'Not estimated':`${l.flight_time_hours} hr`)}${row('Alternate',l.alternate_icao)}${row('Payload',JSON.stringify(l.payload||{}))}`)}${card('Fuel release (estimated)',formatObj(l.fuel_release))}${card('TOLD / W&B (estimated)',`<div class="subsection">Takeoff and landing</div>${formatObj(l.told)}<div class="subsection">Weight and balance</div>${formatObj(l.weight_balance)}`)}</div><div class="panel-note warn" style="margin-top:12px">AI numerical estimates are for MSFS simulation only. Not certified flight manual performance, dispatch fuel or approved weight and balance.</div></section>`).join('')||'<div class="empty">No usable legs. Research or generation is incomplete.</div>'}
function dispatchAirports(m){const list=A(m.airport_briefings);return `<div class="panel-note" style="margin-bottom:16px">Every departure, arrival and alternate is researched separately. Empty providers do not imply none exist. Published prices are distinguished from non-operative simulation estimates.</div>${list.map(airportCard).join('')||'<div class="empty">Airport research records not returned.</div>'}`}
function airportCard(a){const fb=A(a.fbos),hd=A(a.handlers),fu=A(a.fuels);return `<section class="airport"><div class="actions" style="justify-content:space-between"><h3>${E(a.icao)} / ${E(a.name||'AIRPORT IDENTITY NOT VERIFIED')}</h3><div class="actions">${tag(a.status,a.status==='RESEARCHED'?'ok':a.status==='FAILED'?'fail':'warn')}<button class="button small secondary" data-research-airport="${E(a.icao)}" ${state.taskId?'disabled':''}>↻ Re-research</button></div></div><div class="grid two">${card('Airfield & facilities',`${row('City / country',[a.municipality,a.country].filter(Boolean).join(' / '))}${row('Elevation',a.elevation_ft==null?'Unverified':state.settings.units==='metric'?`${numfmt(a.elevation_ft*.3048)} m MSL`:`${a.elevation_ft} FT MSL`)}${row('Coordinates',a.coordinates)}${row('Runways',A(a.runways).join(' | '))}${row('Frequencies',A(a.frequencies).join(' | '))}${row('Limitations',a.limitations)}${row('Customs / border',a.customs)}${row('Handling',a.handling)}${row('Operating notes',a.operational_notes)}`)}${card('Weather briefing',`${row('METAR',a.weather?.metar)}${row('TAF',a.weather?.taf)}${row('Source',a.weather?.source)}${row('Retrieved UTC',ds(a.weather?.retrieved_at))}${row('Status',a.weather?.status)}<button class="button small ghost" data-weather="${E(a.icao)}">Update NOAA weather</button>`)}</div><div class="section-head"><h2>FBOs (${fb.length}) and ground handlers (${hd.length})</h2></div><div class="grid two">${card('FBO / business aviation',fb.length?fb.map(providerCard).join(''):'<div class="panel-note warn">No source-supported FBO was returned. Research may have failed or providers may not publish details.</div>')}${card('Ground handlers',hd.length?hd.map(providerCard).join(''):'<div class="panel-note warn">Ground handling providers not established by research.</div>')}</div><div class="section-head"><h2>Fuel supply, grade & station price</h2></div>${fu.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Grade / availability</th><th>Price / unit</th><th>Evidence & date</th></tr></thead><tbody>${fu.map(f=>`<tr><td><strong>${E(f.provider)}</strong></td><td>${E(f.grade)}<div class="tiny">${E(f.availability)}</div></td><td>${f.price_amount==null?'<span class="muted">Quote required</span>':`<div class="fuelprice">${E(f.price_amount)} ${E(f.price_currency)} / ${E(f.price_unit)}</div>`}${tag(f.price_type,f.price_type==='PUBLISHED'?'ok':'warn')}</td><td><div class="tiny">${E(f.price_date||'Not published')}</div><div class="tiny">${E(f.price_basis)}</div>${f.source_url?`<a class="source" href="${url(f.source_url)}" target="_blank" rel="noopener noreferrer">Fuel source ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel-note warn">Fuel availability, supplier or price was not established. No real fuel quote is implied.</div>'}<div class="section-head"><h2>Research audit & sources</h2></div>${row('Stage',a.audit?.stage)}${row('Missing fields',A(a.audit?.missing).join(', ')||'None detected')}${a.audit?.error?`<div class="panel-note fail">${E(a.audit.error)}</div>`:''}${textList(a.warnings)}${links(a.sources)}</section>`}
function providerCard(p){return `<div class="provider"><strong>${E(p.name)}</strong>${row('Services',p.services)}${row('Contact',p.contact)}${row('Hours',p.hours)}${row('On-airport location',p.location)}${p.source_url?`<a class="source" href="${url(p.source_url)}" target="_blank" rel="noopener noreferrer">Provider website / evidence ↗</a>`:''}</div>`}
function dispatchMx(m){const d=A(m.mx?.defects);return `<div class="grid two">${card('Simulated aircraft reliability',`${row('Build year',m.aircraft?.year_built)}${row('Age',m.risk?.age_years==null?'Unknown':`${m.risk.age_years} years`)}${row('MX setting',m.mx_status)}${row('Age influences reliability',m.risk?.age_influences_reliability?'YES':'NO')}${row('Weighted risk score',m.risk?.simulation_risk_score)}${row('Band',m.risk?.risk_band)}${row('Scenario status',m.mx?.scenario_status)}<div class="panel-note warn" style="margin-top:14px">Scenario risk is a training setting, not an actual prediction of aircraft reliability or maintenance condition.</div>`)}${card('Maintenance summary',`<p class="prose">${E(m.mx?.notes||'No MX interpretation yet.')}</p><h2 class="route">${d.length} INOP / MEL / CDL scenarios</h2><p class="tiny">Only actual approved operator MEL, AFM, CDL and maintenance documents authorize real-world dispatch.</p>`)}</div>${d.map((x,i)=>`<section class="card" style="margin-top:14px"><h3>${i+1}. ${E(x.equipment)} ${tag(x.category,'warn')}</h3>${row('Symptom',x.symptom)}${row('Operational effect',x.impact)}${row('MEL reference',x.mel_reference||'Unverified')}${row('CDL reference',x.cdl_reference||'Not applicable')}${row('Deferral status',x.deferral_status||'SIMULATION — NOT APPROVED')}${row('Dispatch limitations',x.dispatch_limitations)}${row('Repair requirements',x.repair_action)}<div class="subsection">Steps to recreate in Microsoft Flight Simulator</div>${A(x.msfs_steps).map((z,i)=>`<p class="tiny">${i+1}. ${E(z)}</p>`).join('')||'<div class="tiny">No MSFS steps available for this scenario.</div>'}<div class="subsection">References</div>${links(x.source_urls)}</section>`).join('')}${!d.length?'<div class="panel-note">No equipment defects selected or maintenance interpretation did not complete. Check scenario status above.</div>':''}`}
function dispatchDocs(m){return `<div class="grid two">${card('Crew & manifests',`<div class="subsection">Flight crew</div>${A(m.crew).map(x=>row(O(x).role||'Crew',O(x).name||JSON.stringify(x))).join('')||'<div class="tiny">Not generated</div>'}<div class="subsection">Passenger manifest</div>${A(m.passengers).map(x=>row(O(x).role||'Passenger',O(x).name||JSON.stringify(x))).join('')||'<div class="tiny">None</div>'}<div class="subsection">Cargo manifest</div>${A(m.cargo).map(x=>row(O(x).description||'Cargo',`${O(x).weight_lb??'—'} lb`)).join('')||'<div class="tiny">None</div>'}`)}${card('Controlled dispatch document',`${row('Mission',m.code)}${row('Document status',m.research?.status)}${row('Airport annexes',A(m.airport_briefings).length)}${row('Fuel & flight releases',A(m.legs).length)}${row('INOP / MEL / CDL forms',A(m.mx?.defects).length)}${row('Controlled mission forms',A(m.documents).length)}<p class="tiny">Multipage PDF includes AI-selected controlled forms, mission narrative, aircraft evidence, crew and manifests, each leg's fuel/TOLD/W&B simulation planning, every airport brief, FBOs, handlers, fuel prices, MX/MSFS steps and citation records.</p>${btn('pdf','↓ Download full PDF')}<div class="panel-note warn" style="margin-top:14px">This document is not an authorized flight release. Partial research and missing prices are clearly flagged.</div>`)}</div><div class="section-head"><h2>Mission-specific control forms (${A(m.documents).length})</h2></div>${A(m.documents).length?A(m.documents).map((d,i)=>card(`${i+1}. ${d.title||d.type}`,`${tag(d.status||'SIMULATION — NOT FILED','warn')}${row('Type',d.type)}${row('Purpose',d.purpose)}${row('Intended recipient',d.submit_to)}${row('Applicable legs',A(d.applicable_legs).join(', '))}<div class="subsection">Control document fields</div>${A(d.fields).map(f=>row(f.label,f.value)).join('')||'<div class="tiny">No fields generated</div>'}<div class="subsection">MSFS / dispatch simulation procedure</div><p class="prose">${E(d.instructions)}</p>`)).join(''):'<div class="panel-note warn">AI did not identify any special controlled forms for this mission. Standard crew / cargo manifests and release annexes remain in the PDF.</div>'}` }
function fleet(){const f=state.fleet;return `<div class="grid two">${card('AI aircraft / registration research',`<form id="fleet-form"><div class="field"><label>Registration to verify (optional)</label><input name="registration" placeholder="N721RF / G-XXXX / AI selects"></div><div class="field"><label>Aircraft type / ICAO</label><input name="aircraft_type" placeholder="H25B / C25C / BE58"></div><div class="field"><label>Geographic preference</label><input name="location" placeholder="USA / UK / global"></div><div class="field"><label>Maintenance level</label><select name="mx_status"><option>GOOD</option><option selected>OK</option><option>BAD</option></select></div><label class="checkbox"><input name="age_influence" type="checkbox" checked> Increase simulator INOP risk with aircraft age</label><button type="submit" class="button" ${state.taskId?'disabled':''}>✦ Research actual aircraft + model MX</button></form>`)}${card('Fleet records',`<div class="number" style="font:800 36px Manrope">${f.length}</div><p class="tiny">Aircraft research records saved on this device; genuine public-registration verification is recorded separately from fictional reliability/MX simulation.</p>${btn('open-builder','Generate mission using fleet aircraft','small secondary')}`)}</div><div class="section-head"><h2>Researched aircraft</h2></div>${f.length?f.map(item=>`<section class="card" style="margin-bottom:12px"><div class="actions" style="justify-content:space-between"><h3>${E(item.aircraft?.registration||'NO VERIFIED TAIL')} / ${E(item.aircraft?.model||item.aircraft?.icao_type)}</h3>${tag(item.aircraft?.registration_status,item.aircraft?.registration_status==='VERIFIED'?'ok':'warn')}</div>${row('Year built',item.aircraft?.year_built)}${row('Notes',item.aircraft?.registration_note)}${row('Maintenance setting',item.mx?.risk?.condition)}${row('Risk band',item.mx?.risk?.risk_band)}${row('Simulated defects',A(item.mx?.defects).length)}<div class="subsection">Registration research sources</div>${links(item.aircraft?.registration_sources)}<div class="actions" style="margin-top:12px"><button class="button small secondary" data-fleet-use="${E(item.id)}">Build mission with this aircraft</button><button class="button small danger" data-fleet-remove="${E(item.id)}">Remove</button></div></section>`).join(''):'<div class="empty">No aircraft have been researched yet.</div>'}`}
function flight(){const p=state.vatsim?.pilot,setting=state.settings;return `<div class="grid two">${card('VATSIM connection',`${row('Configured CID',setting.vatsimCid?'Enabled / '+setting.vatsimCid:'No CID configured')}${row('Last live check',ds(state.vatsim?.lastChecked))}${row('Feed status',state.vatsim?.error||'No feed error reported')}${row('Tracking',setting.vatsimEnabled?'Enabled while page open':'Disabled')}<p class="tiny">The public VATSIM data feed contains real-time network snapshots. Sessions are observed every minute while AeroMission is open; snapshots do not establish legal flight time, verified takeoff, actual landing or historical flights.</p><div class="actions">${btn('vatsim-refresh','↻ Refresh live feed')}${btn('open-settings','Set VATSIM CID','secondary')}</div>`)}${card('Observed pilot',p?`${tag('ONLINE','ok')}${row('Callsign',p.callsign)}${row('Aircraft',p.flight_plan?.aircraft)}${row('From / to',`${p.flight_plan?.departure||'—'} → ${p.flight_plan?.arrival||'—'}`)}${row('Alternate',p.flight_plan?.alternate)}${row('Speed',state.settings.units==='metric'?`${numfmt(p.groundspeed_kts*1.852)} km/h`:`${p.groundspeed_kts} KT`)}${row('Altitude',state.settings.units==='metric'?`${numfmt(p.altitude_ft*.3048)} m`:`${p.altitude_ft} FT`)}${row('Position',`${p.lat}, ${p.lon}`)}${row('Heading',p.heading)}${row('VATSIM logon',ds(p.logon_time))}`:'<div class="empty"><strong>No live connection observed</strong>Set your CID under Settings and connect to VATSIM. Offline flights cannot be reconstructed from the live feed.</div>')}</div>${p?card('Filed flight plan',`${row('Route',p.flight_plan?.route)}${row('Flight rules',p.flight_plan?.flight_rules)}${row('Estimated departure',p.flight_plan?.deptime)}${row('Enroute estimate',p.flight_plan?.enroute_time)}${row('Last VATSIM update',ds(p.last_updated))}`):''}`}
function logbook(){const entries=state.logbook;return `${card('VATSIM-assisted simulator logbook',`<div class="panel-note">This logbook records flight-plan and position snapshots when your CID is online. When VATSIM disconnects, the session is marked <strong>arrival unconfirmed</strong>; you can explicitly confirm completion in your local logbook. Historical connections before you enabled monitoring are not available from this public live feed.</div><div class="actions" style="margin-top:13px">${btn('vatsim-refresh','Check VATSIM now')}${btn('export','Export logbook / all data','secondary')}</div>`)}<div class="section-head"><h2>Observed network sessions (${entries.length})</h2></div>${entries.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Callsign / aircraft</th><th>Flight plan</th><th>First seen / last seen</th><th>Observed data</th><th>Status</th><th></th></tr></thead><tbody>${entries.map(x=>`<tr><td class="mono"><strong>${E(x.callsign)}</strong><div class="tiny">${E(x.aircraft)}</div></td><td class="mono">${E(x.origin||'—')} → ${E(x.destination||'—')}</td><td><div class="tiny">${E(ds(x.first_seen))}</div><div class="tiny">${E(ds(x.last_seen))}</div></td><td>${E(x.samples||0)} snapshots<div class="tiny">Max ${E(x.max_altitude_ft||0)} FT / ${E(x.max_groundspeed_kts||0)} KT</div></td><td>${tag(x.status,x.status==='COMPLETED_USER_CONFIRMED'?'ok':x.status==='TRACKING'?'ok':'warn')}</td><td>${x.status==='CONNECTION_ENDED_UNCONFIRMED'?`<button class="button small secondary" data-confirm-log="${E(x.id)}">Confirm flight complete</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No VATSIM sessions captured. The logbook begins recording when your CID is seen online.</div>'}<div class="section-head"><h2>Locally completed simulator missions</h2></div>${missionTable(state.missions.filter(x=>x.status==='COMPLETED'))}`}
function settings(){const s=state.settings;return `<div class="grid two">${card('Application configuration',`<form id="settings-form"><div class="grid-form"><div class="field"><label>Theme</label><select name="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark operations</option><option value="light" ${s.theme==='light'?'selected':''}>Light cockpit</option></select></div><div class="field"><label>Units</label><select name="units"><option value="imperial" ${s.units==='imperial'?'selected':''}>Imperial (FT / LB / GAL)</option><option value="metric" ${s.units==='metric'?'selected':''}>Metric (M / KG / L) — display preference</option></select></div><div class="field"><label>Home base ICAO</label><input name="homeBase" value="${E(s.homeBase)}" placeholder="KIND"></div><div class="field"><label>Default starting area</label><input name="defaultStart" value="${E(s.defaultStart)}" placeholder="KIND / region / city"></div><div class="field"><label>Default PIC name (optional)</label><input name="pic" value="${E(s.pic)}" placeholder="Captain name"></div><div class="field"><label>Default MX condition</label><select name="mxStatus">${['GOOD','OK','BAD'].map(x=>`<option ${s.mxStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>VATSIM CID</label><input name="vatsimCid" inputmode="numeric" pattern="[0-9]{0,10}" value="${E(s.vatsimCid)}" placeholder="Your numeric VATSIM CID"></div><div class="field"><label>Render app passcode (if configured)</label><input name="appPasscode" type="password" value="${E(s.appPasscode||'')}" autocomplete="off" placeholder="Matches optional APP_PASSCODE on Render"></div><div class="field"><label>AI model</label><input disabled value="${E(health.model||'gpt-4.1')}" title="Controlled by OPENAI_MODEL on Render"></div></div><label class="checkbox"><input name="ageInfluence" type="checkbox" ${s.ageInfluence?'checked':''}> Default: age influences maintenance simulation</label><label class="checkbox"><input name="vatsimEnabled" type="checkbox" ${s.vatsimEnabled?'checked':''}> Monitor VATSIM live feed while app is open</label><button class="button" type="submit">Save settings</button></form>`)}${card('AI & data connectivity',`${row('Backend',health.ok?'Version 3 AI rebuild online':'Unavailable')}${row('Model',health.model)}${row('AI configuration',health.aiConfigured?'OPENAI_API_KEY configured':'OPENAI_API_KEY missing')}${row('VATSIM',health.vatsim?'Public VATSIM v3 data feed':'Unavailable')}${row('Local missions',state.missions.length)}${row('Stored sessions',state.logbook.length)}<div class="panel-note warn" style="margin-top:14px">Keep OPENAI_API_KEY only in Render. You can optionally add APP_PASSCODE in Render and enter the same code above to prevent public use of your AI budget. The app's browser passcode is not exported in JSON backups.</div><div class="subsection">Data import / export</div><div class="actions">${btn('export','Export complete JSON backup')}${btn('import','Import JSON backup','secondary')}</div><input id="import-file" type="file" accept=".json,application/json" class="visually-hidden"><p class="tiny">Browser localStorage is per-browser and per-domain. Save a backup before switching domains or clearing data. Import handles v3 backups and attempts best-effort v2 mission conversion.</p>`)}</div><div class="section-head"><h2>Research and generation diagnostic log</h2>${btn('refresh-debug','↻ Refresh log','small secondary')}</div><section class="card"><div id="debug-feed"><p class="tiny">Press Refresh to load backend stage history. Errors are recorded with stage labels.</p></div></section><section class="card" style="margin-top:14px"><h3>Simulation-only limitations</h3><p class="tiny">AeroMission cannot authorize dispatch, certify MEL deferrals, guarantee aircraft registration status, provide real-time aviation advisories, or promise actual retail fuel prices. Source-backed factual data is separated from simulation estimates. VATSIM sessions are public network observations and are not official pilot or maintenance log records.</p></section>`}
const views={dashboard,builder,dispatch,jobs,fleet,flight,logbook,settings};
function bind(){
 $$('[data-nav]').forEach(b=>b.onclick=()=>{state.view=b.dataset.nav;save();shell()});
 $$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;save();shell()});
 $$('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());
 $$('[data-open]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.open;state.tab='overview';state.view='dispatch';save();shell()});
 $$('[data-job]').forEach(b=>b.onclick=()=>{state.jobSelected=b.dataset.job;save();shell()});
 $$('[data-accept]').forEach(b=>b.onclick=()=>acceptJob(b.dataset.accept));
 $$('[data-research-airport]').forEach(b=>b.onclick=()=>researchAirport(b.dataset.researchAirport));
 $$('[data-weather]').forEach(b=>b.onclick=()=>refreshWeather(b.dataset.weather));
 $$('[data-fleet-use]').forEach(b=>b.onclick=()=>{const a=state.fleet.find(x=>x.id===b.dataset.fleetUse);if(!a)return;state.view='builder';save();shell();const form=$('#mission-form');if(form){form.elements.namedItem('aircraft_type').value=a.aircraft?.icao_type||'';form.elements.namedItem('registration').value=a.aircraft?.registration||'';form.elements.namedItem('mx_status').value=a.mx?.risk?.condition||'OK'}notify('Fleet aircraft loaded into mission form')});
 $$('[data-fleet-remove]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this aircraft record?'))return;state.fleet=state.fleet.filter(x=>x.id!==b.dataset.fleetRemove);save();shell()});
 $$('[data-confirm-log]').forEach(b=>b.onclick=()=>{const l=state.logbook.find(x=>x.id===b.dataset.confirmLog);if(l){l.status='COMPLETED_USER_CONFIRMED';l.confirmed_at=new Date().toISOString();l.remarks='User confirmed completion; VATSIM feed alone did not verify landing.';save();shell()}});
 const ms=$('#select-mission');if(ms)ms.onchange=()=>{state.selected=ms.value;save();shell()};
 const missionForm=$('#mission-form');if(missionForm)missionForm.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(missionForm));data.age_influence=missionForm.querySelector('[name="age_influence"]').checked;data.leg_count=data.leg_count?Number(data.leg_count):null;data.pic=state.settings.pic;startTask('/api/tasks/mission',data,'MISSION')};
 const jobsForm=$('#jobs-form');if(jobsForm)jobsForm.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(jobsForm));data.count=Number(data.count||6);startTask('/api/tasks/jobs',data,'JOBS')};
 const fleetForm=$('#fleet-form');if(fleetForm)fleetForm.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(fleetForm));data.age_influence=fleetForm.querySelector('[name="age_influence"]').checked;startTask('/api/tasks/aircraft',data,'AIRCRAFT')};
 const settingsForm=$('#settings-form');if(settingsForm)settingsForm.onsubmit=e=>{e.preventDefault();const s=Object.fromEntries(new FormData(settingsForm));const cid=(s.vatsimCid||'').trim();if(cid&&!/^\d{4,10}$/.test(cid)){notify('VATSIM CID must be 4–10 numeric digits',true);return}state.settings={...state.settings,...s,vatsimCid:cid,ageInfluence:settingsForm.querySelector('[name="ageInfluence"]').checked,vatsimEnabled:settingsForm.querySelector('[name="vatsimEnabled"]').checked};if(!cid)state.vatsim={pilot:null,lastChecked:null,error:null};save();shell();notify('Settings saved');if(cid&&state.settings.vatsimEnabled)void fetchVatsim()};
 const imp=$('#import-file');if(imp)imp.onchange=()=>importData(imp);
}
async function startTask(endpoint,data,kind,context={}){if(state.taskId){notify('An AI task is already running. Wait until it completes, or dismiss the failed task.',true);return}try{const r=await api(endpoint,data);state.taskId=r.id;state.pendingContext={...context,kind};taskState={kind,status:'RUNNING',stage:'QUEUED',detail:'Starting…',history:[]};save();shell();pollTask(r.id)}catch(e){notify('Could not start '+kind+': '+e.message,true)}}
let pollingId=null;
async function pollTask(id){if(pollingId===id)return;pollingId=id;let networkFailures=0;try{while(state.taskId===id){let t;try{t=await api(`/api/tasks/${encodeURIComponent(id)}`);networkFailures=0}catch(e){networkFailures++;if(networkFailures>6){notify('Research polling interrupted: '+e.message+' — task can be resumed by reloading.',true);break}await delay(4500);continue}taskState=t;if(t.partial?.id){upsert(t.partial)}if(['COMPLETE','FAILED'].includes(t.status)){if(t.status==='COMPLETE'){applyTaskResult(t);notify(`${t.kind} completed${t.result?.warning?' — '+t.result.warning:''}`)}else{notify(t.kind+' failed: '+t.error,true);if(t.partial?.id){upsert(t.partial);notify('Partial mission has been retained in Dispatch')}}state.taskId='';state.pendingContext={};save();shell();break}if(['dashboard','builder','jobs','dispatch','fleet','flight'].includes(state.view))shell();await delay(4000)}}finally{pollingId=null}}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function applyTaskResult(t){const out=O(t.result),kind=t.kind,context=O(state.pendingContext);if(kind==='MISSION'&&out.mission){upsert(out.mission);if(context.jobId){const job=state.jobs.find(x=>x.id===context.jobId);if(job)job.status='ASSIGNED'}state.view='dispatch';state.tab='overview'}else if(kind==='JOBS'){state.jobs=A(out.jobs);state.jobSelected=state.jobs[0]?.id||'';state.view='jobs'}else if((kind==='AIRPORT'||kind==='AIRPORTS')){const id=context.missionId||state.selected,m=state.missions.find(x=>x.id===id);if(m){const briefs=kind==='AIRPORT'?A([out.briefing].filter(Boolean)):A(out.briefings);for(const b of briefs){const index=A(m.airport_briefings).findIndex(x=>x.icao===b.icao);if(index>=0)m.airport_briefings[index]=b;else m.airport_briefings.push(b)}m.research=m.research||{};m.research.errors=[...A(m.research.errors).filter(e=>!briefs.some(b=>String(e.subject).includes(b.icao))),...A(out.errors)];m.research.completed_at=new Date().toISOString();m.research.status=m.research.errors.length?'PARTIAL_FAILURE':A(m.airport_briefings).every(b=>b.status==='RESEARCHED')?'COMPLETE':'PARTIAL_DATA';m.research.summary=`${A(m.airport_briefings).filter(b=>b.status==='RESEARCHED').length}/${A(m.airport_briefings).length} airport briefings meet checks after research.`;state.selected=id;state.tab='airports';state.view='dispatch'}}else if(kind==='AIRCRAFT'&&out.aircraft){state.fleet.unshift({id:crypto.randomUUID(),aircraft:out.aircraft,mx:out.mx,created_at:new Date().toISOString()});state.view='fleet'}save()}
async function acceptJob(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;const req={mission_type:j.type,aircraft_type:j.aircraft_type,mx_status:['GOOD','OK','BAD'].includes(j.mx_status)?j.mx_status:'OK',difficulty:j.difficulty,starting_point:j.route[0],leg_count:j.route.length-1,concept:`FULFILL THIS ASSIGNED JOB. Prefer the established route ${j.route.join(' → ')} and keep the logistics consistent. ${j.mission_profile||j.description}`,age_influence:state.settings.ageInfluence};state.pendingJobId=id;save();await startTask('/api/tasks/mission',req,'MISSION',{jobId:id});}
async function researchAirport(icao){await startTask('/api/tasks/airport',{icao},'AIRPORT',{icao,missionId:S()?.id})}
async function refreshWeather(icao){const m=S(),id=m?.id;if(!m)return;notify('Refreshing NOAA weather for '+icao);try{const weather=await api('/api/weather/'+icao);const saved=state.missions.find(x=>x.id===id),brief=A(saved?.airport_briefings).find(x=>x.icao===icao);if(brief){brief.weather=weather;save();shell()}notify(icao+' weather checked')}catch(e){notify('Weather retrieval failed: '+e.message,true)}}
async function pdf(){const m=S();if(!m)return notify('Select a mission first',true);try{notify('Building your multipage dispatch PDF');const r=await fetch('/api/dispatch/pdf',{method:'POST',headers:{'Content-Type':'application/json',...(state.settings.appPasscode?{'X-AeroMission-Passcode':state.settings.appPasscode}:{})},body:JSON.stringify({mission:m})});if(!r.ok){let error=await r.text();try{error=JSON.parse(error).error}catch{}throw Error(String(error).slice(0,250))}if(!(r.headers.get('content-type')||'').includes('application/pdf'))throw Error('Backend did not return a PDF (check Render deployment).');const blob=await r.blob();const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`AeroMission-${m.code||'dispatch'}.pdf`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),12000)}catch(e){notify('PDF generation failed: '+e.message,true)}}
function exportData(){const backup={format:'AeroMission Ops v3',exported_at:new Date().toISOString(),data:{...state,settings:{...state.settings,appPasscode:''},taskId:'',pendingContext:{},vatsim:{pilot:null,lastChecked:state.vatsim?.lastChecked,error:null}}};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`AeroMission-Backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),8000);notify('Complete local backup exported')}
async function importData(inp){try{if(!inp.files?.[0])return;const d=JSON.parse(await inp.files[0].text()),source=d.data||d.db||d;let m=A(source.missions);if(!Array.isArray(source.missions))throw Error('Backup lacks missions array');if(!confirm(`Replace local data with ${m.length} imported missions? Export your current data first.`))return;const fromLegacy=source.schema_version!==3&&d.format!=='AeroMission Ops v3';if(fromLegacy){m=m.map(x=>({...x,id:x.id||x.code||crypto.randomUUID(),code:x.code||'LEGACY',title:x.title||x.mission_title||'Legacy mission',legs:A(x.legs).map((l,i)=>({...l,seq:i+1,origin:(l.origin||'').toUpperCase(),destination:(l.destination||'').toUpperCase()})),airport_briefings:A(x.airport_briefings).map(a=>({...a,icao:(a.icao||'').toUpperCase(),fbos:A(a.fbos),handlers:A(a.handlers),fuels:A(a.fuels||a.fuel),status:a.status||'LEGACY_UNVERIFIED'})),research:x.research||{status:'LEGACY_UNVERIFIED',errors:[]},aircraft:x.aircraft||{},mx:x.mx||{defects:[]}}))}
 state={...defaults,...source,settings:{...defaults.settings,...O(source.settings)},missions:m,jobs:A(source.jobs),fleet:A(source.fleet),logbook:A(source.logbook),taskId:'',pendingContext:{},vatsim:{pilot:null,lastChecked:null,error:null},view:'dashboard',selected:m[0]?.id||''};save();shell();notify(fromLegacy?'Legacy backup imported. Review unverified fields.':'Backup imported.')}catch(e){notify('Import failed: '+e.message,true)}}
async function fetchVatsim(){const cid=state.settings.vatsimCid;if(!cid||!state.settings.vatsimEnabled)return;try{const result=await api('/api/vatsim/pilot?cid='+encodeURIComponent(cid));state.vatsim={pilot:result.pilot,lastChecked:result.checked_at,error:null};recordPilot(result.pilot,result.checked_at);save();if(['flight','logbook','dashboard'].includes(state.view))shell()}catch(e){state.vatsim={...state.vatsim,lastChecked:new Date().toISOString(),error:e.message};save();if(['flight','logbook'].includes(state.view))shell();notify('VATSIM check: '+e.message,true)}}
function recordPilot(p,at){const logs=state.logbook;const current=logs.find(x=>x.source==='VATSIM_LIVE'&&x.status==='TRACKING');if(p){const f=p.flight_plan||{},key=`${p.cid}:${p.callsign}:${p.logon_time}`;let entry=logs.find(x=>x.session_key===key);if(!entry){entry={id:key,session_key:key,source:'VATSIM_LIVE',status:'TRACKING',callsign:p.callsign,aircraft:f.aircraft,origin:f.departure,destination:f.arrival,alternate:f.alternate,route:f.route,first_seen:at,last_seen:at,logon_time:p.logon_time,initial_position:{lat:p.lat,lon:p.lon},last_position:null,max_altitude_ft:0,max_groundspeed_kts:0,samples:0,missing_checks:0};logs.unshift(entry)}entry.status='TRACKING';entry.missing_checks=0;entry.last_seen=at;entry.max_altitude_ft=Math.max(entry.max_altitude_ft||0,p.altitude_ft||0);entry.max_groundspeed_kts=Math.max(entry.max_groundspeed_kts||0,p.groundspeed_kts||0);entry.last_position={lat:p.lat,lon:p.lon,altitude_ft:p.altitude_ft,groundspeed_kts:p.groundspeed_kts};entry.samples=(entry.samples||0)+1;for(const other of logs.filter(x=>x.source==='VATSIM_LIVE'&&x.status==='TRACKING'&&x.session_key!==key)){other.status='CONNECTION_ENDED_UNCONFIRMED';other.ended_at=at}}else if(current){current.missing_checks=(current.missing_checks||0)+1;if(current.missing_checks>=2){current.status='CONNECTION_ENDED_UNCONFIRMED';current.ended_at=at}}state.logbook=logs.slice(0,300)}
async function showDebug(){try{const x=await api('/api/debug');const el=$('#debug-feed');if(el)el.innerHTML=A(x.events).length?A(x.events).map(a=>`<div class="kv"><b>${E(ds(a.at))}<br>${tag(a.level)}</b><span><strong>${E(a.message)}</strong><div class="source">${E(JSON.stringify(a.detail||{}))}</div></span></div>`).join(''):'<p class="tiny">No backend stage events yet.</p>'}catch(e){notify('Debug retrieval failed: '+e.message,true)}}
const actions={
 'open-builder':()=>{state.view='builder';save();shell()},'open-jobs':()=>{state.view='jobs';save();shell()},'open-dispatch':()=>{state.view='dispatch';save();shell()},'open-settings':()=>{state.view='settings';save();shell()},'pdf':pdf,'export':exportData,'import':()=>$('#import-file')?.click(),
 'retry-all':async()=>{const m=S();if(!m)return;const codes=A(m.airport_briefings).map(x=>x.icao).filter(Boolean);if(!codes.length)return notify('Mission has no airports',true);await startTask('/api/tasks/airports',{icaos:codes},'AIRPORTS',{missionId:m.id})},
 'dismiss-task':()=>{if(taskState?.status==='RUNNING'){notify('Research is still running. Keep task active to receive its results.',true);return}state.taskId='';taskState=null;save();shell()},
 'delete-mission':()=>{const m=S();if(!m||!confirm(`Delete mission ${m.code} from this browser?`))return;state.missions=state.missions.filter(x=>x.id!==m.id);state.selected=state.missions[0]?.id||'';save();shell()},
 'vatsim-refresh':()=>{if(!state.settings.vatsimCid)return notify('Set VATSIM CID in Settings first',true);void fetchVatsim()},'refresh-debug':showDebug,
 'complete-mission':()=>{const m=S();if(m&&confirm('Mark this simulator mission completed? VATSIM flight data is not proof of landing.')){m.status='COMPLETED';m.completed_at=new Date().toISOString();save();shell()}}
};
async function startup(){shell();try{health=await api('/api/health')}catch(e){notify('Server check failed: '+e.message,true)}shell();if(state.taskId)pollTask(state.taskId);if(state.settings.vatsimCid&&state.settings.vatsimEnabled)void fetchVatsim();flightTimer=setInterval(()=>{if(document.visibilityState==='visible'&&state.settings.vatsimCid&&state.settings.vatsimEnabled)void fetchVatsim()},60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.settings.vatsimCid&&state.settings.vatsimEnabled&&Date.now()-Date.parse(state.vatsim?.lastChecked||0)>60000)void fetchVatsim()})}
startup();
